#!/usr/bin/env bash\nset -euo pipefail\n\n# Mock rationale: Use a temporary HOME directory so the test never touches the real user files.\nTMP_HOME=$(mktemp -d)\nexport HOME="${TMP_HOME}"\n# Define a tiny list of dotfiles for the test environment.\nexport DOTFILE_LIST=".testrc .testconfig"\n\n# Create dummy dotfiles with known content.\necho "original rc" > "${HOME}/.testrc"\necho "original config" > "${HOME}/.testconfig"\n\n# Locate the utility script.\nSCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/../src" && pwd)\nSCRIPT="${SCRIPT_DIR}/main.sh"\n\n# Perform a backup.\n"${SCRIPT}" backup\n\n# Capture the list of backups.\nlist_output=$("${SCRIPT}" list)\nif [[ -z "${list_output}" ]]; then\n  echo "FAIL: No backups were listed"\n  exit 1\nfi\nbackup_id=$(echo "${list_output}" | head -n1)\n\n# Mutate the original files to simulate user changes.\necho "modified rc" > "${HOME}/.testrc"\necho "modified config" > "${HOME}/.testconfig"\n\n# Restore the previously created backup.\n"${SCRIPT}" restore "${backup_id}"\n\n# Verify that the original contents have been restored.\nif ! grep -q "original rc" "${HOME}/.testrc"; then\n  echo "FAIL: .testrc was not restored correctly"\n  exit 1\nfi\nif ! grep -q "original config" "${HOME}/.testconfig"; then\n  echo "FAIL: .testconfig was not restored correctly"\n  exit 1\nfi\n\necho "PASS"\nexit 0\n
